mapper.update:
UPDATE kb_upload_session
SET uploaded_chunks = #{uploadedChunks}, uploaded_bytes = #{uploadedBytes}, update_time = NOW()
WHERE upload_id = #{uploadId}

UPDATE kb_upload_session
SET status = #{status}, error_message = #{errorMessage}, update_time = NOW()
WHERE upload_id = #{uploadId}

mapper.select:
SELECT * FROM kb_upload_session
WHERE expire_time < #{expireTime}
  AND status IN ('UPLOADING', 'FAILED')
